param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}

$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('DefaultEncodingFactories'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('probe');$builder=$module.DefineType('ArrayEncoding',[Reflection.TypeAttributes]'Public,Sealed',[Text.Encoding]);$fields=@{};foreach($name in @('Multiplier','CountMode','WriteMode')){$fields[$name]=$builder.DefineField($name,[int],[Reflection.FieldAttributes]::Public)};$fields.Trace=$builder.DefineField('Trace',[Collections.Generic.List[int[]]],[Reflection.FieldAttributes]::Public)
$constructor=$builder.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,[type[]]@());$il=$constructor.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Call,[Text.Encoding].GetConstructor([Reflection.BindingFlags]'Instance,NonPublic',$null,[type[]]@(),$null));$il.Emit([Reflection.Emit.OpCodes]::Ret)
foreach($abstract in [Text.Encoding].GetMethods()|Where-Object IsAbstract){[type[]]$parameters=@($abstract.GetParameters()|ForEach-Object ParameterType);$method=$builder.DefineMethod($abstract.Name,[Reflection.MethodAttributes]'Public,Virtual,HideBySig',$abstract.ReturnType,$parameters);$il=$method.GetILGenerator();$write=$abstract.Name -in @('GetBytes','GetChars');$count=$abstract.Name -in @('GetByteCount','GetCharCount');if($write -or $count){$kind=switch($abstract.Name){GetByteCount{0}GetBytes{1}GetCharCount{2}GetChars{3}};$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields.Trace);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_4);$il.Emit([Reflection.Emit.OpCodes]::Newarr,[int]);foreach($i in 0..3){$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$i);switch($i){0{$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$kind)}1{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2)}2{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3)}3{if($write){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]5)}else{$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1)}}};$il.Emit([Reflection.Emit.OpCodes]::Stelem_I4)};$il.Emit([Reflection.Emit.OpCodes]::Callvirt,[Collections.Generic.List[int[]]].GetMethod('Add'))
 $mode=$il.DeclareLocal([int]);$normal=$il.DefineLabel();$nonNegative=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields[$(if($write){'WriteMode'}else{'CountMode'})]);$il.Emit([Reflection.Emit.OpCodes]::Stloc,$mode)
 if($write){$skip=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ble,$skip);$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]5);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,42);$il.Emit($(if($abstract.Name -eq 'GetBytes'){[Reflection.Emit.OpCodes]::Stelem_I1}else{[Reflection.Emit.OpCodes]::Stelem_I2}));$il.MarkLabel($skip)}
 $il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$normal);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'array callback failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($normal);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_2);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$nonNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($nonNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields.Multiplier);$il.Emit([Reflection.Emit.OpCodes]::Mul);$il.Emit([Reflection.Emit.OpCodes]::Ret)
 }else{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ret)};$builder.DefineMethodOverride($method,$abstract)}

foreach($kind in @(1,2)){[type[]]$parameters=if($kind -eq 1){@([int])}else{@([int],[Text.EncoderFallback],[Text.DecoderFallback])};$constructor=$builder.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,$parameters);$il=$constructor.GetILGenerator();foreach($i in 0..$parameters.Length){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]$i)};$il.Emit([Reflection.Emit.OpCodes]::Call,[Text.Encoding].GetConstructor([Reflection.BindingFlags]'Instance,NonPublic',$null,$parameters,$null));$il.Emit([Reflection.Emit.OpCodes]::Ret)}
$type=$builder.CreateType();$rows=[Collections.Generic.List[object]]::new()
function Failure($e){while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null});actualValue=$(if($e -is [ArgumentOutOfRangeException]){$e.ActualValue}else{$null});message=$e.Message}}
function Preamble($owner){return ,($owner.GetPreamble())}
$utf8Empty=Preamble ([Text.UTF8Encoding]::new($false));if($utf8Empty -isnot [byte[]]){throw 'Typed empty UTF8 preamble required'}
function Snapshots($owners,$providedE,$providedD,$mutE,$mutD){$states=[Collections.Generic.List[object]]::new();foreach($owner in $owners){$e=$owner.EncoderFallback;$d=$owner.DecoderFallback;$p=Preamble $owner;if($p -isnot [byte[]] -or $p.Length -ne 0){throw 'Typed empty base preamble required'};$states.Add([ordered]@{readOnly=$owner.IsReadOnly;codePage=$owner.CodePage;singleByte=$owner.IsSingleByte;encoderType=$e.GetType().FullName;decoderType=$d.GetType().FullName;encoderMax=$e.MaxCharCount;decoderMax=$d.MaxCharCount;encoderUnits=$(if($e -is [Text.EncoderReplacementFallback]){,[int[]][char[]]$e.DefaultString}else{$null});decoderUnits=$(if($d -is [Text.DecoderReplacementFallback]){,[int[]][char[]]$d.DefaultString}else{$null});identity=@([object]::ReferenceEquals($e,[Text.EncoderFallback]::ReplacementFallback),[object]::ReferenceEquals($d,[Text.DecoderFallback]::ReplacementFallback),[object]::ReferenceEquals($e,$providedE),[object]::ReferenceEquals($d,$providedD),[object]::ReferenceEquals($e,$mutE),[object]::ReferenceEquals($d,$mutD),[object]::ReferenceEquals($p,(Preamble $owner)),[object]::ReferenceEquals($p,(Preamble $owners[0])),[object]::ReferenceEquals($p,$utf8Empty));preambleLength=$p.Length})};return ,($states.ToArray())}
$actions=@(@('Read',0),@('SetEncoder',0),@('SetDecoder',0),@('NullEncoder',0),@('NullDecoder',0),@('Clone',0),@('SetEncoder',1),@('SetDecoder',1),@('NullEncoder',1),@('NullDecoder',1),@('Clone',1),@('ResetEncoder',2),@('ResetDecoder',2),@('Read',1),@('Read',0),@('Read',2))
foreach($kind in 0..2){foreach($codePage in $(if($kind -eq 0){@(0)}else{@(-2147483648,-1,0,1,65001,65535,65536,2147483647)})){foreach($profile in $(if($kind -eq 2){@(0,1,2,3,4,5,6)}else{@(0)})){$providedE=$null;$providedD=$null;switch($profile){1{$providedE=[Text.EncoderReplacementFallback]::new('AB');$providedD=[Text.DecoderReplacementFallback]::new('CD')}2{$providedE=[Text.EncoderReplacementFallback]::new('');$providedD=[Text.DecoderReplacementFallback]::new('')}3{$value=[string]::new([char[]]@(0xD800,0xDC00));$providedE=[Text.EncoderReplacementFallback]::new($value);$providedD=[Text.DecoderReplacementFallback]::new($value)}4{$providedE=[Text.EncoderFallback]::ExceptionFallback;$providedD=[Text.DecoderFallback]::ExceptionFallback}5{$providedD=[Text.DecoderReplacementFallback]::new('CD')}6{$providedE=[Text.EncoderReplacementFallback]::new('AB')}};$mutE=[Text.EncoderReplacementFallback]::new('XY');$mutD=[Text.DecoderReplacementFallback]::new('ZW');$owners=[Collections.Generic.List[Text.Encoding]]::new();$initial=$null;$steps=[Collections.Generic.List[object]]::new()
try{$owner=switch($kind){0{$type.GetConstructor([type[]]@()).Invoke([object[]]@())}1{$type.GetConstructor([type[]]@([int])).Invoke([object[]]@([int]$codePage))}2{$type.GetConstructor([type[]]@([int],[Text.EncoderFallback],[Text.DecoderFallback])).Invoke([object[]]@([int]$codePage,$providedE,$providedD))}};$owners.Add($owner);$result=[ordered]@{ok=$true};$initial=Snapshots $owners $providedE $providedD $mutE $mutD}catch{$result=Failure $_.Exception}
if($result.ok){foreach($action in $actions){$owner=$owners[[int]$action[1]];try{switch($action[0]){SetEncoder{$owner.EncoderFallback=$mutE}SetDecoder{$owner.DecoderFallback=$mutD}NullEncoder{[Text.Encoding].GetProperty('EncoderFallback').SetMethod.Invoke($owner,[object[]]@($null))|Out-Null}NullDecoder{[Text.Encoding].GetProperty('DecoderFallback').SetMethod.Invoke($owner,[object[]]@($null))|Out-Null}Clone{$owners.Add([Text.Encoding]$owner.Clone())}ResetEncoder{$owner.EncoderFallback=[Text.EncoderFallback]::ReplacementFallback}ResetDecoder{$owner.DecoderFallback=[Text.DecoderFallback]::ReplacementFallback}Read{}};$outcome=[ordered]@{ok=$true}}catch{$outcome=Failure $_.Exception};$steps.Add([ordered]@{operation=[string]$action[0];target=[int]$action[1];result=$outcome;states=(Snapshots $owners $providedE $providedD $mutE $mutD)})}}
$rows.Add([ordered]@{kind=$kind;codePage=$codePage;profile=$profile;result=$result;initial=$initial;steps=$steps.ToArray()})
}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();rows=$rows.ToArray();qualification='SELECTED_GENERIC_ENCODING_CONSTRUCTORS_FALLBACK_CLONE_CODEPAGE_PREAMBLE_ONLY; METADATA_TABLES_CUSTOM_CALLBACKS_FULL_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 16 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS generic Encoding defaults: $($rows.Count) constructor profiles"
